async function viewSearch(e){e.innerHTML=`<div class="pagehead"><div><h1>Search</h1><p>Across expenses, income, bills, acte, credits, cars, properties and lists.</p></div></div>\n    <div class="card">\n      <input id="sq" type="search" placeholder="Digi, pasaport, Kaufland…" value="${esc(SEARCH_Q)}" autocomplete="off" style="font-size:16px">\n      <p class="muted" style="margin:8px 0 0">${tr("Tip: press Ctrl+K (or /) anywhere to search without leaving the page.")}</p>\n      <div id="sres" style="margin-top:12px"></div>\n    </div>`;const t=$("#sres"),a=$("#sq"),s=async()=>{const e=a.value.trim();if(SEARCH_Q=e,e.length<2)return void(t.innerHTML='<p class="muted">Type at least 2 characters.</p>');const{results:s}=await api("/search?q="+encodeURIComponent(e));s.length?(t.innerHTML=`<p class="muted">${s.length} ${tr(1===s.length?"result":"results")}</p>\n      <table class="cards"><tbody>${s.map(e=>`<tr>\n        <td data-label="${tr("Type")}"><span class="badge role">${tr(SEARCH_KINDS[e.kind]||e.kind)}</span></td>\n        <td><b>${esc(e.title||"")}</b>${e.sub?`<br><span class="muted">${esc(e.sub)}</span>`:""}</td>\n        <td data-label="${tr("Date")}">${e.date?fdate(e.date):""}</td>\n        <td class="right amount" data-label="${tr("Amount")}">${null!=e.amount?moneyIn(e.amount,e.currency):""}</td>\n        <td class="right"><a class="btn ghost small" href="#${e.tab}" data-go="${e.kind}">${tr("View")}</a></td>\n      </tr>`).join("")}</tbody></table>`,t.querySelectorAll("[data-go]").forEach(e=>e.onclick=()=>{const t=e.dataset.go,a={expense:"expenses",income:"income",credit:"credits",loan:"debt",goal:"savings"};a[t]&&(PENDING_MONEY_TAB=a[t]),"expense"===t&&(PENDING_EXPENSE_FILTER={q:SEARCH_Q,month:"all",who:"all",cat:"all"})})):t.innerHTML=`<div class="empty"><b>Nothing found</b>No match for "${esc(e)}".</div>`};a.oninput=()=>{clearTimeout(a._h),a._h=setTimeout(s,250)},a.focus(),SEARCH_Q?s():t.innerHTML='<p class="muted">Type at least 2 characters.</p>'}